        if cells:
            data.append([c.get_text(strip=True) for c in cells])
    if not data:
        return pd.DataFrame()
    if table.find('th'):
        header_row = data[0]
        body_rows = data[1:] if len(data) > 1 else []
        if not body_rows:
            return pd.DataFrame(columns=header_row)
        df = pd.DataFrame(body_rows, columns=header_row)
    else:
        df = pd.DataFrame(data)
    return df
